#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll power(ll b, ll e, ll mod) {
    ll r = 1 % mod;
    for (b %= mod; e; e >>= 1, b = b * b % mod)
        if (e & 1) r = r * b % mod;
    return r;
}

// Inverse of a unit modulo q by the extended Euclidean algorithm.
ll inverse(ll a, ll q) {
    ll g = q, x = 0, x1 = 1, a1 = a % q;
    while (a1) {
        ll t = g / a1;
        tie(g, a1) = make_pair(a1, g - t * a1);
        tie(x, x1) = make_pair(x1, x - t * x1);
    }
    return (x % q + q) % q;
}

// Catalan(n) modulo p^a, handling the factors of p separately.
ll catalanResidue(ll n, ll p, int a) {
    ll q = 1;
    for (int i = 0; i < a; i++) q *= p;
    vector<ll> prefix(q + 1, 1);  // product of 1..r that are not multiples of p, mod q
    for (ll i = 1; i <= q; i++) prefix[i] = prefix[i - 1] * (i % p ? i : 1) % q;
    auto unitFactorial = [&](ll k) {
        ll result = 1;
        for (; k; k /= p) result = result * power(prefix[q], k / q, q) % q * prefix[k % q] % q;
        return result;
    };
    auto valuation = [&](ll k) {
        ll result = 0;
        while (k) {
            k /= p;
            result += k;
        }
        return result;
    };
    ll divisor = n + 1, removed = 0;
    while (divisor % p == 0) {
        divisor /= p;
        removed++;
    }
    ll exponent = valuation(2 * n) - 2 * valuation(n) - removed;
    if (exponent >= a) return 0;
    ll uf = unitFactorial(n);
    ll denominator = uf * uf % q * (divisor % q) % q;
    return unitFactorial(2 * n) * inverse(denominator, q) % q * power(p, exponent, q) % q;
}

int main() {
    ll n;
    cin >> n;
    ll a = catalanResidue(n, 2, 4), b = catalanResidue(n, 5, 4);
    // CRT: 16 * 586 = 1 (mod 625).
    cout << a + 16 * ((((b - a) * 586) % 625 + 625) % 625) << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static long power(long b, long e, long mod) {
        long r = 1 % mod;
        for (b %= mod; e > 0; e >>= 1, b = b * b % mod)
            if ((e & 1) == 1) r = r * b % mod;
        return r;
    }

    // Inverse of a unit modulo q by the extended Euclidean algorithm.
    static long inverse(long a, long q) {
        long g = q, x = 0, x1 = 1, a1 = a % q;
        while (a1 != 0) {
            long t = g / a1, ng = g - t * a1, nx = x - t * x1;
            g = a1;
            a1 = ng;
            x = x1;
            x1 = nx;
        }
        return (x % q + q) % q;
    }

    // Catalan(n) modulo p^a, handling the factors of p separately.
    static long catalanResidue(long n, long p, int a) {
        long q = 1;
        for (int i = 0; i < a; i++) q *= p;
        long[] prefix = new long[(int) q + 1];  // product of 1..r that are not multiples of p, mod q
        prefix[0] = 1;
        for (int i = 1; i <= q; i++) prefix[i] = prefix[i - 1] * (i % p != 0 ? i : 1) % q;
        long divisor = n + 1, removed = 0;
        while (divisor % p == 0) {
            divisor /= p;
            removed++;
        }
        long exponent = valuation(2 * n, p) - 2 * valuation(n, p) - removed;
        if (exponent >= a) return 0;
        long uf = unitFactorial(n, p, q, prefix);
        long denominator = uf * uf % q * (divisor % q) % q;
        return unitFactorial(2 * n, p, q, prefix) * inverse(denominator, q) % q * power(p, exponent, q) % q;
    }

    static long unitFactorial(long k, long p, long q, long[] prefix) {
        long result = 1;
        for (; k > 0; k /= p) result = result * power(prefix[(int) q], k / q, q) % q * prefix[(int) (k % q)] % q;
        return result;
    }

    static long valuation(long k, long p) {
        long result = 0;
        while (k > 0) {
            k /= p;
            result += k;
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong();
        long a = catalanResidue(n, 2, 4), b = catalanResidue(n, 5, 4);
        // CRT: 16 * 586 = 1 (mod 625).
        System.out.println(a + 16 * ((((b - a) * 586) % 625 + 625) % 625));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func power(b, e, mod int) int {
	r := 1 % mod
	for b %= mod; e > 0; e, b = e>>1, b*b%mod {
		if e&1 == 1 {
			r = r * b % mod
		}
	}
	return r
}

// inverse returns the inverse of a unit modulo q by the extended Euclidean algorithm.
func inverse(a, q int) int {
	g, x, x1, a1 := q, 0, 1, a%q
	for a1 != 0 {
		t := g / a1
		g, a1 = a1, g-t*a1
		x, x1 = x1, x-t*x1
	}
	return (x%q + q) % q
}

// catalanResidue returns Catalan(n) modulo p^a, handling the factors of p separately.
func catalanResidue(n, p, a int) int {
	q := 1
	for i := 0; i < a; i++ {
		q *= p
	}
	prefix := make([]int, q+1) // product of 1..r that are not multiples of p, mod q
	prefix[0] = 1
	for i := 1; i <= q; i++ {
		f := 1
		if i%p != 0 {
			f = i
		}
		prefix[i] = prefix[i-1] * f % q
	}
	unitFactorial := func(k int) int {
		result := 1
		for ; k > 0; k /= p {
			result = result * power(prefix[q], k/q, q) % q * prefix[k%q] % q
		}
		return result
	}
	valuation := func(k int) int {
		result := 0
		for k > 0 {
			k /= p
			result += k
		}
		return result
	}
	divisor, removed := n+1, 0
	for divisor%p == 0 {
		divisor /= p
		removed++
	}
	exponent := valuation(2*n) - 2*valuation(n) - removed
	if exponent >= a {
		return 0
	}
	uf := unitFactorial(n)
	denominator := uf * uf % q * (divisor % q) % q
	return unitFactorial(2*n) * inverse(denominator, q) % q * power(p, exponent, q) % q
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	a, b := catalanResidue(n, 2, 4), catalanResidue(n, 5, 4)
	// CRT: 16 * 586 = 1 (mod 625).
	fmt.Println(a + 16*((((b-a)*586)%625+625)%625))
}
